def _moment_problems(root: Path, declared: Declaration) -> list[Diagnostic]:
    """What each row leaves unsettled: a missing referent, or one the tree does not have."""
    return [
        note for moment in declared.moments for note in _absence_problems(root, declared.slug, moment)
    ]


def _absence_problems(root: Path, slug: str, moment: Moment) -> list[Diagnostic]:
    """One absence row's problems — a moment's, or an allowlist row's read through the same grammar."""
    notes = _row_problems(slug, moment)
    if moment.kind not in ("elsewhere", "embedded", "not yet"):
        return notes
    if not moment.referent:
        # A `not yet` names its ticket in a straw-dog binding; without one the gap is nobody's.
        # TODO docs/tickets/01-0010.0130-harness-installs-into-another-tree.md: the shear strips
        # the binding on install, so in a recipient an unbound `not yet` is upstream's gap and
        # must pass; which tree is the origin is the fact that ticket records.
        problem = "unbound: no <straw-dog ticket=…> binding" if moment.kind == "not yet" else "names nothing"
        return notes + [Diagnostic(slug, f"'{moment.occasion}' is {moment.kind} and {problem}")]
    named = moment.referent
    if not (root / named).exists():
        notes.append(Diagnostic(slug, f"'{moment.occasion}' names {named}, which does not resolve"))
    elif moment.kind == "not yet" and "/done/" in f"/{named}":
        # A gap is a promise of future work, and a closed ticket does no future work: the row
        # looks assigned and is assigned to nothing. This is also where a row that named the
        # ticket declaring its own mechanism ends up the day after that ticket closes.
        notes.append(
            Diagnostic(
                slug, f"'{moment.occasion}' names {named}, an archived ticket; closed work fills no gap"
            )
        )
    return notes


def _allowlist(root: Path) -> list[Allowed]:
    """The allowlist's rows as written. No file is an empty list; every unclaimed skill says so itself."""
    record = root / ALLOWLIST
    if not record.is_file():
        return []
    rows = []
    for cells in _first_table(record.read_text(encoding="utf-8")):
        what, absence = (cells + ["", ""])[:2]
        kind, why, referent = _absence(absence)
        rows.append(Allowed(_backticked(what) or what, kind, why, referent))
    return rows


def _first_table(text: str) -> list[list[str]]:
    """The one table the allowlist holds, wherever the preamble ends; header and separator dropped."""
    lines = text.splitlines()
    first = next((at for at, line in enumerate(lines) if line.startswith("|")), None)
    if first is None:
        return []
    table = []
    for line in lines[first:]:
        if not line.startswith("|"):
            break
        table.append(_cells(line))
    return table[2:]


def _skills(root: Path, declarations: list[Declaration], allowlist: list[Allowed]) -> list[Skill]:
    """Every installed skill with who claims it: the declaration naming it, or its allowlist row."""
    home = root / SKILLS
    skills = []
    for directory in sorted(path for path in home.glob("*") if path.is_dir()) if home.is_dir() else []:
        named = f"{SKILLS}/{directory.name}/"
        by = [declared.slug for declared in declarations if declared.instruction == f"{named}SKILL.md"]
        allowed = next((row for row in allowlist if row.what == named), None)
        skills.append(Skill(named, by, allowed))
    return skills


def _allowlist_problems(
    root: Path, declarations: list[Declaration], allowlist: list[Allowed]
) -> list[Diagnostic]:
    """Whether each row is the claim an allowlist row makes: nothing owns this, for a stated reason."""
    notes = []
    for row in allowlist:
        where = f"allowlist row `{row.what}`"
        if row.kind is not None and row.kind not in ALLOWED_KINDS:
            notes.append(Diagnostic("allowlist", f"{where} is {row.kind}; a row claims nothing owns it"))
            continue
        notes += _absence_problems(root, "allowlist", Moment(row.what, None, row.kind, row.why, row.referent))
        # A place under docs/ is what a recipient creates for itself; only core paths must be here.
        if row.what.startswith(".agents/") and not (root / row.what).exists():
            notes.append(Diagnostic("allowlist", f"{where} does not resolve"))
        naming = [declared.slug for declared in declarations if declared.instruction == f"{row.what}SKILL.md"]
        if naming:
            notes.append(Diagnostic("allowlist", f"{where} is named by {', '.join(naming)} and allowlisted"))
    return notes


def _skill_problems(skills: list[Skill]) -> list[Diagnostic]:
    """A skill is one mechanism's instruction file, or allowlisted — never both claims, never neither."""
    notes = []
    for skill in skills:
        if len(skill.named_by) > 1:
            notes.append(Diagnostic("allowlist", f"{skill.directory} is named by {' and '.join(skill.named_by)}"))
        elif not skill.named_by and skill.allowed is None:
            notes.append(
                Diagnostic(
                    "allowlist", f"no mechanism names {skill.directory} and the allowlist does not hold it"
                )
            )
    return notes

